/*
 * A105265  Concatenation of letters of words obtained from axiom "1" and the
 *          iterates of the substitutions '1' -> "12", '2' -> "3", '3' -> "4",
 *          '4' -> "1".
 * https://oeis.org/A105265
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy, less
 * Formula:   The sequence is the infinite word generated by iterating the
 *            substitution 1 → 12 2 → 3 3 → 4 4 → 1 and appending each image
 *            to the current word. We store the word incrementally and return
 *            the nth symbol (0‑based). The word grows roughly twice its
 *            previous length, so the algorithm is O(n)
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

/* global storage for the incremental word */
static seq_t *seq = NULL;
static size_t len = 0;   /* number of symbols stored */
static size_t cap = 0;   /* allocated capacity */

seq_t a(idx_t n)
{
    /* initialise on first call */
    if (seq == NULL) {
        cap = 64;
        seq = (seq_t*)malloc(cap * sizeof(seq_t));
        if (!seq) return (seq_t)0;               /* unlikely */
        seq[0]  = (seq_t)1;                      /* axiom */
        len    = 1;
    }

    /* grow until the word contains n+1 symbols */
    while (len <= (size_t)n) {
        size_t cur_len = len;                    /* current length before expansion */

        /* worst case: each symbol may contribute 3 new symbols
           (current symbol + its image).  That guarantees enough
           capacity for the new word. */
        size_t needed = cur_len * 3;
        if (cap < needed) {
            size_t new_cap = (cap ? cap << 1 : 64);
            while (new_cap < needed) new_cap <<= 1;
            seq_t *tmp = (seq_t*)realloc(seq, new_cap * sizeof(seq_t));
            if (!tmp) return (seq_t)0;           /* allocation failed */
            seq = tmp;
            cap = new_cap;
        }

        /* append the image of each symbol in the current word */
        for (size_t i = 0; i < cur_len; ++i) {
            seq_t v = seq[i];
            if (v == (seq_t)1) {
                seq[len++] = (seq_t)1;
                seq[len++] = (seq_t)2;
            } else if (v == (seq_t)2) {
                seq[len++] = (seq_t)3;
            } else if (v == (seq_t)3) {
                seq[len++] = (seq_t)4;
            } else if (v == (seq_t)4) {
                seq[len++] = (seq_t)1;
            }
            /*  no other symbols can appear  */
        }
    }

    return seq[n];
}
